import sys

def main():
    input = sys.stdin.read().strip().split('\n')
    index = 0
    while True:
        n = int(input[index])
        if n == 0:
            break
        perm = list(map(int, input[index + 1].split()))
        inverse_perm = [0] * n
        for i, p in enumerate(perm):
            inverse_perm[p - 1] = i + 1
        if perm == inverse_perm:
            print('ambiguous')
        else:
            print('not ambiguous')
        index += 2

main()
